INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (60984, 'spa', 'Título divino cristológico', 'Alfa como título cristológico y teológico: la primera letra del alfabeto griego que funciona como autodesignación divina con el significado de ''el Primero'' o ''el Principio''. Emparejada con Omega en los cuatro pasajes de Apocalipsis (1:8, 11; 21:6; 22:13), forma un merismo que reclama soberanía sobre toda la existencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (60985, 'spa', 'Aarón (nombre propio)', 'Nombre propio Aarón (hebreo אַהֲרוֹן), hermano de Moisés y sumo sacerdote fundacional de Israel. En el uso neotestamentario, Aarón funciona principalmente como tipo sacerdotal: Hebreos argumenta que el sacerdocio de Jesús supera el orden aarónico (Heb 5:4; 7:11), y el contenido del arca incluye la vara florecida de Aarón (Heb 9:4). Lucas 1:5 ancla el linaje sacerdotal del Bautista en la línea de Aarón.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (60988, 'spa', 'Invocación filial a Dios', 'Conserva el vocativo arameo que Jesús usaba al dirigirse a Dios, adoptado luego por los creyentes llenos del Espíritu. La transliteración en todas las lenguas mantiene su estatus especial como término técnico cristiano. La fórmula dual de Pablo (''¡Abbá! ¡Padre!'') une la adoración arameoparlante y grecohablante, señalando la universalidad de la filiación adoptiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (60989, 'spa', 'Nombre propio bíblico', 'Abel como nombre propio que designa al segundo hijo justo de Adán, figura tipológica del martirio fiel en el Nuevo Testamento. Mateo 23:35 y Lucas 11:51 citan su sangre como inicio del sufrimiento inocente, mientras que Hebreos 11:4 y 12:24 desarrollan su significado teológico: una fe que habla incluso después de la muerte.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (60990, 'spa', 'Nombre propio bíblico', 'Designa tanto a un monarca judío en la ascendencia de Jesús como a un orden sacerdotal en el culto del templo. Mateo lo sitúa en el linaje real; Lucas, en la rotación sacerdotal de Zacarías. Esta doble referencia conecta la legitimidad davídica con los orígenes proféticos del Bautista, subrayando la continuidad del plan redentor de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (60993, 'spa', 'Nombre propio', 'Las traducciones en distintos idiomas conservan el nombre de forma prácticamente idéntica: Abiud, Abioúd. Su doble aparición en Mateo 1:13 establece su lugar en la genealogía mesiánica. Aunque históricamente desconocido, Abiud representa la fiel preservación de la línea de David a través de generaciones silenciosas entre el exilio y la venida del Mesías.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (60994, 'spa', 'Abraham', 'Nombre propio del patriarca Abraham, padre de Isaac y abuelo de Jacob, a quien Dios otorgó el pacto fundacional de promesa (Gn 12:1-3; 15:6; 17:5). En el Nuevo Testamento aparece como paradigma de la fe (Ro 4:3; Gá 3:6-9; He 11:8-19), antepasado invocado en las genealogías (Mt 1:1-2) y figura cuyo «seno» simboliza el descanso bienaventurado (Lc 16:22).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (60996, 'spa', 'Abismo', 'El abismo como profundidad cosmológica o prisión del inframundo: un vasto reino sin fondo asociado con el caos, el confinamiento de espíritus malignos y la morada de los muertos. En Lucas 8:31 los demonios suplican no ser arrojados al abismo; en Apocalipsis 9:1-2, 11 es un pozo sellado del que emergen fuerzas destructoras bajo un rey demoníaco. Romanos 10:7 lo emplea como el reino de los muertos del cual Cristo resucitó.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61000, 'spa', 'Profeta cristiano', 'Las traducciones muestran leves variaciones ortográficas —en griego Ἅγαβος frente a Ἀγαβος, en español Ágabos o Hágabos— pero todas preservan el mismo nombre mediante transliteración. Sus dos apariciones en Hechos lo establecen como profeta reconocido cuya palabra tenía autoridad. La predicción de la hambruna (Hechos 11:28) motivó esfuerzos de socorro, y la advertencia sobre el encarcelamiento (Hechos 21:10) puso a prueba la determinación de Pablo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61001, 'spa', 'Obrar el bien', 'Las traducciones multilingües enfatizan consistentemente la acción: en español ''hacer bien'', en francés ''faire le bien'', en alemán formas que preservan la estructura participial griega. Ambas apariciones presentan a Dios o a los creyentes como agentes activos del bien: Dios obrando a través de la abundancia de la creación (Hechos 14:17), y los creyentes mediante el compartir generoso (1 Timoteo 6:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61002, 'spa', 'Hacer el bien — Realizar acciones moralmente buenas, bondadosas o beneficiosas, ', 'Hacer el bien — Realizar acciones moralmente buenas, bondadosas o beneficiosas, abarcando tanto la obediencia ética como la benevolencia activa. Jesús lo usa para plantear la cuestión sabática sobre salvar la vida frente a destruirla (Marcos 3:4; Lucas 6:9), y luego lo extiende al mandamiento radical de amar a los enemigos (Lucas 6:27, 33, 35). Pedro emplea el término para los cristianos que soportan un trato injusto mientras continúan obrando rectamente (1 Pedro 2:15, 20; 3:6, 17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61011, 'spa', 'bueno (cualidad moral)', 'Uso adjetival que describe personas, acciones o cosas como moralmente buenas, virtuosas, rectas o beneficiosas. Es el sentido predominante (85 veces), desde el buen árbol y buen fruto del Sermón del Monte (Mt 7:17-18) hasta el «siervo bueno y fiel» (Mt 25:21) y la «buena tierra» de la parábola del sembrador (Lc 8:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61014, 'spa', 'bienes, cosas buenas', 'Uso sustantivado que designa cosas buenas, bendiciones o bienes materiales y espirituales, generalmente en plural o con artículo. El Magnificat de María declara a los hambrientos «colmados de bienes» (Lc 1:53); el rico insensato planea almacenar sus «bienes» (Lc 12:18-19). Mt 7:11 pregunta cuánto más el Padre dará «cosas buenas» a quienes pidan.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61022, 'spa', 'el bien (abstracto)', 'Uso sustantivado abstracto que denota «el bien» como concepto o principio moral — la bondad en sí misma, no bienes específicos. Romanos 12:9 exhorta a «aferraos a lo bueno»; Romanos 12:21 insta a «vencer el mal con el bien»; Hebreos 13:21 ora para que Dios capacite «en toda buena obra». Solo tres ocurrencias portan este peso filosófico plenamente abstracto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61030, 'spa', 'Bondad moral activa', 'Bondad moral activa, rectitud generosa que supera la simple decencia pasiva para expresar carácter benevolente en la práctica. Las cuatro apariciones neotestamentarias son paulinas: fruto del Espíritu (Gál 5:22), «fruto de la luz» junto a justicia y verdad (Ef 5:9), cualidad de creyentes maduros (Rom 15:14) y don divino (2 Tes 1:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61031, 'spa', 'Gozo exultante', 'Alegría intensa y exuberante, frecuentemente asociada con la actividad divina y la esperanza escatológica. Se distingue del gozo ordinario (χαρά) por su cualidad elevada, a menudo extática. El infante Juan salta de ἀγαλλίασις ante la presencia del Mesías (Lucas 1:44), los creyentes comen juntos en este espíritu (Hechos 2:46), y Cristo es presentado «sin mancha ante su gloria con sumo gozo» (Judas 24).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61032, 'spa', 'Regocijarse grandemente, exultar — Exultar, regocijarse intensamente o saltar de', 'Regocijarse grandemente, exultar — Exultar, regocijarse intensamente o saltar de alegría, un gozo arraigado en la actividad redentora de Dios más que en meras circunstancias. Se usa para la respuesta del Magníficat de María (Lucas 1:47), la acción de gracias de Jesús lleno del Espíritu (Lucas 10:21), el gozo anticipado de Abraham en Cristo (Juan 8:56) y el deleite temporal de los discípulos con Juan el Bautista (Juan 5:35). Las Bienaventuranzas ordenan esta exultación bajo persecución (Mateo 5:12), y Pedro la describe como gozo inefable en Cristo aún no visto (1 Pedro 1:6, 8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61040, 'spa', 'Sin cónyuge actual', 'Soltero/a, no casado/a: describe a una persona actualmente sin cónyuge, ya sea por no haberse casado nunca, por viudez o por separación. Las cuatro apariciones neotestamentarias se encuentran en el argumento sostenido de Pablo en 1 Corintios 7 sobre los méritos relativos de la vida casada y la soltera. La evidencia interlingüística apunta uniformemente al estado civil presente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61041, 'spa', 'Indignarse', 'Sentir y expresar fuerte disgusto o indignacion moral ante una ofensa o injusticia percibida. La evidencia multilingue es notablemente uniforme: el espanol emplea consistentemente ''indignarse'', el frances ''s''indigner'' y el ingles ''be indignant'', confirmando un unico sentido indiferenciado. En Mt 20:24 los diez discipulos se indignan por la peticion de Jacobo y Juan; en Mr 10:14 Jesus mismo se indigna cuando impiden el acceso de los ninos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61047, 'spa', 'amar activamente', 'El verbo activo «amar» en todas sus formas finitas e infinitivas — amor deliberado y volitivo dirigido a personas o a Dios — con 133 de 143 ocurrencias. Es el amor mandado en la cita del Shemá (Mt 22:37; Mc 12:30; Lc 10:27), extendido al prójimo (Mt 19:19; Ro 13:9; Gá 5:14) e incluso a los enemigos (Mt 5:44; Lc 6:27, 35).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61063, 'spa', 'amado, que ha sido amado', 'El participio perfecto pasivo ἠγαπημένος/-η/-οι usado como adjetivo sustantivado que significa «amado» o como título de tratamiento «amados» — 8 ocurrencias donde la forma verbal se ha cristalizado en una designación relacional. Pablo se dirige a los romanos como amados de Dios (Ro 9:25), y los colosenses son llamados «escogidos de Dios, santos y amados» (Col 3:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61076, 'spa', 'ser amado (pasivo)', 'Formas pasivas no participiales que indican la experiencia de ser amado o recibir amor — 2 ocurrencias donde la voz pasiva gramatical resalta al receptor en lugar del agente del amor. Juan 14:21 promete que «el que me ama será amado por mi Padre», estableciendo una cadena de amor del discípulo al Hijo y al Padre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61088, 'spa', 'amor', 'El concepto englobante de amor (115 veces), que abarca el amor divino, el amor humano hacia Dios y el amor mutuo entre creyentes. Es la palabra detrás de «Dios es amor» (1 Jn 4:8), la promesa de Jesús de que el amor identificará a sus discípulos (Jn 13:35) y la declaración de Pablo de que nada nos separará del amor de Dios (Ro 8:35-39).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61090, 'spa', 'fiestas de amor', 'Uso concreto y plural excepcional (1 vez) que designa las «fiestas de amor» del cristianismo primitivo — comidas comunitarias que expresaban comunión y caridad. Judas 1:12 advierte sobre falsos maestros que son «escollos en vuestras fiestas de amor». Este uso ofrece evidencia preciosa de una práctica litúrgica convertida en término técnico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61091, 'spa', 'amado, querido', 'Adjetivo que expresa un amor profundo y entrañable, empleado en dos contextos principales: como título divino de Jesús («este es mi Hijo amado», Mt 3:17; 17:5; Mr 1:11), donde evoca al Siervo isaiano y la ligadura de Isaac; y como tratamiento cálido entre creyentes en las epístolas («amados hermanos», 1 Co 15:58; Fil 4:1; 1 Jn 4:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61098, 'spa', 'Figura alegórica', 'Las traducciones muestran ligeras variaciones en la grafía griega (Ἁγάρ, Ἁγὰρ con diferencias de acento), pero todas conservan el nombre hebreo Agar mediante transliteración. La doble referencia de Pablo en Gálatas 4:24-25 establece el marco alegórico: Agar = pacto sinaítico = esclavitud = Jerusalén terrenal. Su identidad como figura conocida del Antiguo Testamento es reinterpretada por Pablo dentro de la argumentación sobre ley y promesa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61099, 'spa', 'Requisición forzada de servicio', 'Denota la coacción autoritaria para prestar servicio, práctica conocida por los judíos tanto bajo la ocupación persa como la romana. Jesús transforma este símbolo de opresión en ocasión de generosidad radical: duplicar voluntariamente el servicio impuesto subvierte la dinámica de poder. La enseñanza convierte la humillación en testimonio del Reino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61100, 'spa', 'Recipiente o vasija', 'Las traducciones multilingües muestran variación según el contexto: en español ''cestas'' para la escena de pesca y ''vasijas'' para las lámparas de aceite; en francés ''vases''; en alemán se preservan formas cercanas al griego. Ambos pasajes de Mateo enfatizan recipientes diseñados para su contenido: vasijas para los peces clasificados (13:48) y vasijas para el aceite de las lámparas (25:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61101, 'spa', 'Mensaje proclamado', 'Las traducciones multilingües enfatizan uniformemente el concepto de mensaje: español «mensaje», francés préservant le grec ἀγγελία, alemán «Botschaft». Ambas apariciones en 1 Juan introducen enseñanza apostólica central: la naturaleza de Dios (1:5) y el mandamiento de amar (3:11). La etimología conecta con ἄγγελος (mensajero), subrayando que se trata de algo entregado, anunciado y proclamado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61102, 'spa', 'ángel celestial', 'Ser sobrenatural celestial que sirve como agente, guardián o heraldo de Dios — anuncia mensajes divinos, protege al pueblo de Dios, ejecuta juicios y adora en el cielo. Los ángeles aparecen en cada momento crucial: el nacimiento de Jesús (Mt 1:20; Lc 2:9), las tentaciones (Mt 4:11), la resurrección (Mt 28:2) y la escatología apocalíptica (Ap 8-16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61107, 'spa', 'mensajero humano', 'Un mensajero, enviado o representante humano despachado en una misión específica. El español distingue claramente entre «ángel» y «mensajero», separando este sentido del sobrenatural. Se aplica a Juan el Bautista como precursor profetizado del Mesías (Mt 11:10; Mc 1:2, citando Mal 3:1), a los mensajeros que Juan envió a Jesús (Lc 7:24) y a los enviados de Jesús (Lc 9:52).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61112, 'spa', 'Manada', 'Manada o rebano de animales que pastan o se desplazan en grupo. Todas las apariciones en el NT se refieren a la piara de cerdos en los relatos del endemoniado gadareno. El espanol ''manada'', el frances ''troupeau'' y el aleman ''Herde'' convergen en un significado unico sin variacion. El sentido clasico de bandas organizadas de jovenes o bancos de peces nunca aparece en el uso biblico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61115, 'spa', 'Hacer santo, purificar o santificar', 'Hacer santo, purificar o santificar: el sentido dominante (24 ocurrencias) que describe la acción transformadora de Dios sobre personas u objetos, haciéndolos santos. Jesús santifica a sus seguidores mediante la verdad (Juan 17:17, 19) y su propia ofrenda (Heb 10:10). En Mateo 23:17, 19, el templo y el altar santifican el oro y la ofrenda puestos sobre ellos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61121, 'spa', 'Reverenciar como santo', 'Reverenciar como santo: tratar el nombre, el carácter o la persona de Dios con reverencia sagrada. Se encuentra en el Padrenuestro (Mt 6:9, Lc 11:2) y en 1 Pedro 3:15 (''santificad a Cristo como Señor en vuestros corazones''). Aquí la dirección se invierte: el ser humano reconoce y declara la santidad existente de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61129, 'spa', 'Consagrarse a la santidad o permitir ser hecho santo, apareciendo una vez en Apo', 'Consagrarse a la santidad o permitir ser hecho santo, apareciendo una vez en Apocalipsis 22:11 como exhortación escatológica: ''el santo, santifíquese todavía.'' Este sentido interior apunta a la santificación personal continua como un estado permanente, no como un evento único, completando la tríada de direcciones de la santificación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61135, 'spa', 'Santidad, santificación — El proceso y el estado resultante de ser consagrado a ', 'Santidad, santificación — El proceso y el estado resultante de ser consagrado a Dios, abarcando tanto la separación inicial en la conversión como la transformación moral continua. Pablo lo presenta como la voluntad divina para los creyentes (1 Tesalonicenses 4:3), el fruto de la liberación del pecado (Romanos 6:19, 22) y un don encarnado en Cristo (1 Corintios 1:30). Hebreos 12:14 lo establece como requisito indispensable para ver a Dios. 1 Timoteo 2:15 y 2 Tesalonicenses 2:13 confirman que la santificación es tanto obra del Espíritu como llamado a la perseverancia en la fe.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61137, 'spa', 'el Santo, Espíritu Santo', 'Uso sustantivo singular que designa al Espíritu Santo (πνεῦμα ἅγιον) o «el Santo» como título divino — el grupo más numeroso con 98 ocurrencias. Cubre las referencias al Espíritu en los Evangelios, Hechos y las epístolas. La traducción es consistente como título propio: Espíritu Santo (español), Saint-Esprit (francés), Heiliger Geist (alemán).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61138, 'spa', 'santo, sagrado, consagrado', 'Adjetivo atributivo o predicativo que describe cosas, lugares o personas como sagradas, apartadas o consagradas a Dios — 65 ocurrencias. La «santa ciudad» (Mt 4:5), el «lugar santo» en la profecía de Daniel (Mt 24:15), la «tierra santa» (Hch 7:33) y las «santas Escrituras» (Ro 1:2) pertenecen a este sentido. Es la acepción adjetival básica de la cual derivan los usos sustantivados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61139, 'spa', 'santos, los consagrados', 'Sustantivo plural que designa al pueblo de Dios — «los santos», «los consagrados» (οἱ ἅγιοι) — 61 ocurrencias concentradas en Hechos y las epístolas paulinas. Pablo saluda a «todos los santos en Cristo Jesús» (Fil 1:1); Pedro visita a «los santos en Lida» (Hch 9:32); los santos resucitados salen de las tumbas en la crucifixión (Mt 27:52).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61140, 'spa', 'lugar santo, santuario', 'Uso sustantivo neutro que se refiere a espacios sagrados — el santuario, el lugar santo o el lugar santísimo (τὰ ἅγια, ἅγια ἁγίων) — 11 ocurrencias, casi todas en Hebreos 8-10. El autor de Hebreos usa τὰ ἅγια para el santuario celestial al que Cristo entra como sumo sacerdote (He 8:2; 9:12), mientras que ἅγια ἁγίων designa la cámara más interior tras el velo (He 9:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61152, 'spa', 'Consagración moral a Dios', 'Denota la consagración moral integral a Dios. En Romanos se usa como atributo del Espíritu mismo — fuente y norma de santidad. Las aplicaciones éticas de Pablo (2 Co 7:1, purificarse de contaminación; 1 Ts 3:13, corazones irreprensibles en la venida de Cristo) muestran la santidad como proceso continuo y meta escatológica del creyente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61155, 'spa', 'Ancla marítima y metafórica', 'Ancla: el pesado implemento de hierro arrojado desde un barco para asegurarlo. Tres de las cuatro apariciones se encuentran en la narrativa de la tormenta en Hechos 27, donde las anclas se echan, fingen y cortan. En Hebreos 6:19 el mismo sustantivo sirve como metáfora de la esperanza cristiana, firme y segura, que penetra más allá del velo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61156, 'spa', 'Tela sin encoger', 'Las traducciones multilingües destacan el estado sin encoger: español «sin encoger», francés «non foulé» (no abatanado), alemán conservando el adjetivo griego. Ambos pasajes evangélicos emplean este término en la parábola de Jesús sobre la incompatibilidad de un parche nuevo en vestido viejo. La evidencia interlingüística apunta consistentemente a una tela que no ha pasado por el proceso de abatanado o encogimiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61157, 'spa', 'Pureza moral', 'Las traducciones multilingües enfatizan uniformemente la pureza: español «pureza», francés preservando la forma dativa griega ἁγνείᾳ, alemán «Reinheit». Ambos pasajes de 1 Timoteo exigen pureza en la conducta visible (4:12) y en los límites relacionales (5:2). El contexto subraya la santidad moral y sexual más que la limpieza ceremonial, apuntando a una santidad práctica vivida en las relaciones cotidianas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61158, 'spa', 'Purificarse', 'Voz media o pasiva: purificarse o ser purificado, principalmente en el contexto de la purificacion ceremonial judia. En Hch 21:24 y 21:26 se describe a Pablo sometido a purificacion ritual en el templo para demostrar su respeto por la ley. Hch 24:18 senala que Pablo estaba ''habiendose purificado'' cuando fue hallado en el templo. Santiago 4:8 extiende la imagen al ambito moral: ''purificad vuestros corazones''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61160, 'spa', 'Purificar (activo)', 'Sentido activo transitivo: purificar a alguien o algo, hacer limpio. En Jn 11:55 muchos subieron antes de la Pascua para purificarse (aqui la forma activa con fuerza reflexiva). Primera de Pedro 1:22 habla de haber purificado el alma mediante la obediencia a la verdad, y 1 Jn 3:3 declara que todo el que tiene esta esperanza en Cristo ''se purifica a si mismo'' asi como Cristo es puro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61166, 'spa', 'Ignorar o desconocer', 'Ignorar o desconocer: el sentido activo de carecer de conocimiento o conciencia, que abarca la gran mayoría de las ocurrencias (19 de 22). Los discípulos ''no entendían'' las palabras de Jesús sobre la resurrección (Mc 9:32), y los jerosolimitanos cumplieron la profecía porque ''no conocieron'' las voces de los profetas (Hch 13:27). En Hechos 17:23, Pablo identifica un altar inscrito ''al Dios no conocido.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61172, 'spa', 'Ser desconocido o no reconocido por otros', 'Ser desconocido o no reconocido por otros: el sentido pasivo, atestiguado en dos ocurrencias. En 2 Cor 6:9, Pablo se describe a sí mismo y a sus compañeros como ''desconocidos'' (ἀγνοούμενοι) pero bien conocidos, una paradoja. En Gál 1:22, Pablo era personalmente desconocido para las iglesias de Judea. El cambio de la ignorancia activa al anonimato pasivo marca una transición semántica significativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61178, 'spa', 'Ser desatendido o ignorado deliberadamente', 'Ser desatendido o ignorado deliberadamente: un uso raro y textualmente debatido en 1 Cor 14:38, donde el verbo lleva un matiz de descuido voluntario o rechazo en lugar de simple desconocimiento. Pablo advierte que quien ''ignore'' el mandato será él mismo ''ignorado.'' Algunos manuscritos leen la forma activa mientras otros la pasiva, pero ambas lecturas preservan la simetría retributiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61183, 'spa', 'Ignorancia espiritual', 'Ignorancia, falta de conocimiento: estado de desconocimiento, especialmente respecto a la voluntad, identidad o exigencias morales de Dios. Pedro atribuye caritativamente la complicidad judía en la muerte de Cristo a la ignorancia (Acts 3:17), mientras que Pablo presenta toda la religión pagana anterior al evangelio como un período de ignorancia que Dios pasó por alto con gracia (Acts 17:30). En Eph 4:18 la ignorancia se vincula con la dureza de corazón.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61184, 'spa', 'Puro, casto', 'Puro, casto, moralmente inocente: describe a personas, conductas o caracteres libres de contaminación, corrupción o doblez. En 2 Co 7:11 los corintios se demostraron ''puros'' mediante su arrepentimiento; en 2 Co 11:2 Pablo visualiza a la iglesia como una ''virgen pura'' desposada con Cristo; Fil 4:8 lo incluye entre las cualidades dignas de contemplación; 1 Ti 5:22 exhorta a Timoteo a mantenerse puro; y Tit 2:5 lo aplica a la castidad de las mujeres jóvenes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61187, 'spa', 'Integridad sincera', 'Las traducciones multilingües enfatizan consistentemente la pureza: español «pureza», francés «pureté», alemán «Reinheit». Los contextos de 2 Corintios amplían la pureza más allá de la ética sexual para abarcar la integridad ministerial (6:6) y la fidelidad doctrinal (11:3). Pablo teme la pérdida de la devoción pura a Cristo mediante la seducción doctrinal. La evidencia interlingüística apoya este sentido como integridad moral integral y sinceridad de corazón.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61189, 'spa', 'Ignorancia culpable', 'Las traducciones multilingües coinciden en «ignorancia»: español «ignorancia», francés «ignorance», alemán «Unwissenheit». Ambos pasajes neotestamentarios tratan la ignorancia como algo culpable y peligroso: ignorancia de Dios dentro de la iglesia (1 Cor 15:34) e ignorancia necia silenciada por la conducta cristiana (1 Pe 2:15). La evidencia interlingüística confirma que se trata de una falta culpable de conocimiento con implicaciones morales y espirituales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61191, 'spa', 'Plaza, mercado público — La plaza pública abierta de una ciudad grecorromana o p', 'Plaza, mercado público — La plaza pública abierta de una ciudad grecorromana o palestina que servía como centro del comercio, la vida social y la actividad cívica. Jesús la usa como escenario de parábolas sobre la inconstancia infantil (Mateo 11:16; Lucas 7:32), para exponer el amor de los fariseos por el reconocimiento público (Mateo 23:7; Marcos 12:38; Lucas 11:43, 20:46) y como lugar donde los jornaleros ociosos esperan ser contratados (Mateo 20:3). Los enfermos son llevados a las plazas para recibir sanidad (Marcos 6:56), y las preocupaciones de pureza ritual surgen del contacto en este espacio público (Marcos 7:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61194, 'spa', 'Comprar bienes en el mercado — adquirir alimentos, propiedades o mercancías en u', 'Comprar bienes en el mercado — adquirir alimentos, propiedades o mercancías en una transacción comercial. Abarca las compras cotidianas: comprar comida para la multitud (Mt 14:15), adquirir un campo o una perla de gran valor (Mt 13:44, 46) y comerciar en los atrios del templo (Mt 21:12; Mr 11:15). El español ''comprar'' expresa el acto comercial directo sin connotaciones teológicas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61200, 'spa', 'Comprar o redimir personas — adquirir o redimir personas, especialmente como met', 'Comprar o redimir personas — adquirir o redimir personas, especialmente como metáfora teológica de la obra expiatoria de Cristo. Pablo declara «fuisteis comprados por precio» (1 Co 6:20; 7:23), y Apocalipsis celebra al Cordero que «compraste» para Dios personas de toda tribu y lengua con su sangre (Ap 5:9; 14:3-4). El español ''comprados'' conserva la metáfora comercial aplicada a la redención.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61213, 'spa', 'Del mercado o foro', 'Las traducciones multilingües reflejan la amplitud del término: el español distingue «audiencias» (sesiones judiciales, Hch 19:38) de «del mercado» (Hch 17:5); el francés usa «du marché»; el alemán conserva las formas griegas. En Hechos 17:5 designa a los vagabundos ociosos de la plaza, mientras que en Hechos 19:38 se refiere a los días señalados para celebrar juicios, mostrando la flexibilidad del vocablo entre lo social y lo jurídico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61214, 'spa', 'Captura de peces', 'Las traducciones multilingües subrayan consistentemente la captura: el español «pesca», el francés «prise» (toma), el alemán conserva las formas griegas en distintos casos. Ambos pasajes de Lucas 5 se centran en la abundancia milagrosa: la pesca anticipada (5:4) y la realidad abrumadora (5:9) que rompía las redes. La evidencia multilingüe confirma este sentido como la redada o captura de peces.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61218, 'spa', 'Olivo silvestre', 'Las traducciones multilingües resaltan unánimemente el carácter silvestre: español «olivo silvestre», francés «olivier sauvage», alemán «wilder Oelbaum». Ambos pasajes de Romanos 11 desarrollan la metáfora hortícola del olivo silvestre frente al cultivado, donde los gentiles son la rama silvestre injertada. La evidencia multilingüe confirma que se trata del olivo que crece de forma natural, sin cultivo humano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61219, 'spa', 'Estado natural e indómito', 'Señala lo que permanece en su estado natural, sin cultivar ni domesticar. La dieta del Bautista — langostas y miel silvestre — establece su identidad como profeta del desierto, sustentado por lo que la naturaleza provee. La metáfora de Judas explota la connotación de caos incontrolado: como olas bravas que rompen sin freno, los falsos maestros esparcen su propia vergüenza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61220, 'spa', 'Herodes Agripa II — Herodes Agripa II (Marcus Julius Agrippa), el último goberna', 'Herodes Agripa II — Herodes Agripa II (Marcus Julius Agrippa), el último gobernante herodiano, que administraba territorios en el norte de Palestina bajo supervisión romana. Las once apariciones en el NT se encuentran en Hechos 25:13–26:32, donde visita a Festo en Cesarea y escucha la defensa de Pablo. Su respuesta a la apelación de Pablo — ''Por poco me persuades a hacerme cristiano'' (Hechos 26:28) — y su veredicto de que Pablo podría haber sido puesto en libertad si no hubiera apelado al César (Hechos 26:32) lo presentan como un juez que reconoce la inocencia de Pablo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61221, 'spa', 'Campo, terreno — un terreno específico y delimitado, ya sea cultivado, comprado ', 'Campo, terreno — un terreno específico y delimitado, ya sea cultivado, comprado o empleado en una parábola. Las parábolas de Jesús sobre el sembrador (Mt 13:24), el tesoro escondido (Mt 13:44) y el trigo y la cizaña giran en torno a este sentido: el campo como parcela definida con dueño. El ''campo del alfarero'' de Mt 27:7 y el ''Campo de Sangre'' de Hch 1:18-19 también pertenecen a esta acepción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61222, 'spa', 'Campos, campiña — el campo abierto o los alrededores rurales de una población, g', 'Campos, campiña — el campo abierto o los alrededores rurales de una población, generalmente en plural. Cuando Jesús dice a los discípulos que las multitudes pueden ir ''a los campos'' a comprar alimento (Mr 6:36), o cuando los que cuidan cerdos huyen ''al campo'' (Mr 5:14), el término designa territorio rural abierto, no una parcela individual. El español ''campos'' o ''campiña'' capta este sentido expansivo y no urbano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61227, 'spa', 'Vigilancia espiritual', 'Velar, mantenerse alerta: conservar una disposición de vigilancia espiritual constante, frecuentemente asociada con la oración. El sentido clásico literal de pasar la noche despierto se convierte en el NT en metáfora de atención espiritual sostenida. Jesús lo emplea escatológicamente: ''Velad y orad'' (Mark 13:33; Luke 21:36). Pablo lo extiende a la perseverancia intercesora en favor de todos los santos (Eph 6:18). En Heb 13:17 describe la responsabilidad pastoral de cuidar las almas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61228, 'spa', 'Vigilias y desvelos', 'Las traducciones multilingües destacan el insomnio y la vigilia: español «vigilias», francés «veille» (desvelo), alemán «Wachsamkeit» (vigilancia). Ambos pasajes de 2 Corintios enumeran este padecimiento junto con trabajos, azotes y hambre. El plural sugiere episodios repetidos o prolongados. La evidencia multilingüe confirma que se trata de noches en vela como parte del costo del servicio apostólico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61229, 'spa', 'ir, vamos', 'Uso intransitivo con significado de «ir» o «venir», funcionando como exhortación más que como transporte de otra persona. Casi todos los casos emplean el subjuntivo exhortativo ἄγωμεν («vamos»): Jesús en Getsemaní (Mt 26:46; Mr 14:42) y camino a la tumba de Lázaro (Jn 11:7, 15). El imperativo ἄγε («¡vamos!») en Mr 1:38 es igualmente intransitivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61230, 'spa', 'traer, llevar', 'Sentido físico dominante: traer, llevar o conducir a una persona de un lugar a otro, presente en más de tres cuartas partes de las ocurrencias. Incluye traer hacia el hablante (Mt 21:7, el pollino), llevar lejos (Lc 4:1, el Espíritu lleva a Jesús al desierto) y escoltar bajo custodia (Mr 13:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61241, 'spa', 'celebrar, realizar', 'Sentido cívico en Hechos 19:38: los tribunales «se celebran» (ἀγοραῖοι ἄγονται). Aquí ἄγω significa conducir o celebrar un procedimiento, no mover a una persona. Aunque solo aparece una vez en el NT, este uso cívico está bien atestiguado en el griego clásico para la celebración de festivales, juicios y asambleas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61248, 'spa', 'transcurrir, pasar', 'Sentido temporal en Lucas 24:21, donde los discípulos de Emaús dicen que «ya es el tercer día que esto acontece»: el tercer día está transcurriendo desde aquellos sucesos. El verbo expresa duración transcurrida en lugar de desplazamiento espacial, un uso idiomático temporal distinto tanto de la escolta física como de la guía figurada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61249, 'spa', 'guiar, conducir', 'Conducción figurada o espiritual por el Espíritu Santo, fuerzas morales o principios abstractos. Romanos 8:14 y Gálatas 5:18 describen a los creyentes «guiados por el Espíritu»; 1 Corintios 12:2 recuerda el haber sido «arrastrados» hacia ídolos mudos. 2 Timoteo 3:6 extiende esto a la manipulación engañosa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61271, 'spa', 'Lucha, conflicto', 'Lucha, pelea o conflicto: el sentido general de esfuerzo intenso o combate espiritual. Pablo lo emplea para la contienda continua de la fe en Fil 1:30, la oposicion enfrentada al proclamar el evangelio en Tesalonica (1 Ts 2:2) y las declaraciones culminantes de 1 Ti 6:12 y 2 Ti 4:7 sobre pelear la buena batalla. El espanol lucha y pelea, el frances y aleman Kampf convergen en la imagen de un combate.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61273, 'spa', 'Carrera (atletica)', 'Carrera o competicion atletica, especificamente la metafora de la carrera a pie. En Hebreos 12:1 se exhorta a los creyentes a correr con perseverancia la carrera (ἀγῶνα) que tienen por delante, rodeados de una gran nube de testigos. El espanol carrera separa nitidamente este sentido de la imagen del combate, mientras que el frances y el aleman mantienen Kampf, lo que sugiere que el certamen atletico estaba menos diferenciado lexicamente en esas tradiciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61275, 'spa', 'Esforzarse espiritualmente', 'Esfuerzo espiritual ferviente, contender en la fe, la oración o el ministerio. Es el sentido dominante en el Nuevo Testamento, apareciendo seis veces. Pablo trabaja ''esforzándose según su poder'' (Col 1:29), Epafras ''lucha constantemente'' en oración (Col 4:12), y a Timoteo se le encarga ''pelear la buena batalla de la fe'' (1 Ti 6:12; cf. 2 Ti 4:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61278, 'spa', 'Competir (metáfora atlética)', 'Competir en un certamen atlético, usado como metáfora de la vida cristiana disciplinada. En 1 Co 9:25 Pablo compara al creyente con atletas que ejercen dominio propio en todo. La metáfora evoca el entrenamiento riguroso y la concentración inquebrantable propios de los juegos griegos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61279, 'spa', 'Pelear, combatir (literal)', 'Lucha física o combate literal. Jesús declara en Juan 18:36 que si su reino fuera de este mundo, sus servidores ''pelearían'' para impedir su arresto. Es el único pasaje del Nuevo Testamento donde este verbo conserva su sentido inequívocamente marcial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61282, 'spa', 'Adán (nombre propio)', 'Nombre propio del primer ser humano, progenitor de toda la raza humana. Aparece en Lucas 3:38 como el ancestro último en la genealogía de Jesús, y en la teología paulina (Ro 5:14; 1 Co 15:22, 45) como la cabeza tipológica de la humanidad caída cuya desobediencia es revertida por Cristo, el ''postrer Adán''. También se menciona en 1 Ti 2:13-14 respecto al orden de la creación y en Judas 14 con referencia cronológica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61286, 'spa', 'Hermana', 'Hermana: una mujer del mismo parentesco sanguíneo o, por extensión, una creyente en la comunidad de fe. Literalmente designa a Marta, María y las hermanas de Jesús (Mt 13:56; Mc 6:3; Jn 11:1). Jesús redefinió el término espiritualmente: ''todo aquel que hace la voluntad de mi Padre es mi hermano y hermana'' (Mt 12:50; Mc 3:35). Pablo lo usa para colaboradoras como Febe (Rom 16:1), dándole al término una calidez eclesial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61289, 'spa', 'hermano, correligionario', 'Un varón que es hermano biológico o, con mucha mayor frecuencia en el NT, miembro de la comunidad creyente al que se trata con calidez familiar. La raíz etimológica (α- copulativa + δελφύς, «útero») subraya un origen compartido — sea biológico o espiritual. Las cartas de Pablo acumulan el sentido comunitario (Ro 1:13; 1 Co 1:10), mientras el sentido literal de parentesco aparece en los relatos evangélicos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61299, 'spa', 'Hermandad en Cristo', 'Las traducciones multilingües lo rinden uniformemente como hermandad: español «hermandad», francés con distintas formas del mismo vocablo griego, alemán «Bruederschaft». Ambos pasajes de 1 Pedro enfatizan la realidad y las exigencias del parentesco espiritual: el amor fraternal como mandato (2:17) y el sufrimiento compartido por la hermandad mundial (5:9). La evidencia multilingüe confirma que se trata de la comunidad de fe como familia espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61300, 'spa', 'Oculto o incierto', 'Las traducciones multilinges revelan el matiz contextual: el español emplea ‘inadvertidas’ (para los sepulcros ocultos) e ‘incierto’ (para la trompeta confusa). Lucas 11:44 enfatiza lo físicamente escondido; 1 Corintios 14:8 enfatiza la señal comunicativamente ambigua. La evidencia abarca desde lo oculto a la vista hasta lo poco claro en su significado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61303, 'spa', 'Angustia espiritual profunda', 'Capta una aflicción emocional y espiritual abrumadora que va más allá del dolor común. En Getsemaní, el uso muestra la agonía humana de Jesús ante la cruz, una angustia tan intensa que aparece junto a «triste hasta la muerte». La inquietud de Epafrodito era una ansiedad inversa: no su propio sufrimiento, sino la preocupación de otros por él turbaba su espíritu.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61305, 'spa', 'Hades (reino de los muertos) — El reino invisible de los muertos en el discurso ', 'Hades (reino de los muertos) — El reino invisible de los muertos en el discurso escatológico y cosmológico del Nuevo Testamento, que funciona como el equivalente griego del שְׁאוֹל hebreo. Se emplea en advertencias de juicio divino (Mt 11:23; Lc 10:15), en la declaración de Cristo sobre la indestructibilidad de la iglesia frente al dominio de la muerte (Mt 16:18), en la parábola que describe la experiencia consciente después de la muerte (Lc 16:23) y en la proclamación apostólica de la resurrección (Hch 2:27, 31).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61310, 'spa', 'Continuo sin cesar', 'Las traducciones multilinges subrayan uniformemente la cualidad incesante: español ‘incesante’, francés ‘sans cesse’, alemán ‘unaufhörlich’. Ambos pasajes describen estados internos que permanecen continuos: el dolor de Pablo (Rom 9:2) y su recuerdo en oración (2 Tim 1:3). La evidencia respalda el sentido de aquello que no cesa, continuo sin interrupción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61311, 'spa', 'Sin cesar', 'Incesantemente, sin interrupción: describe una acción realizada de forma constante y persistente, sin pausas significativas. Los cuatro usos neotestamentarios son paulinos y se refieren a la oración o la acción de gracias. La intercesión habitual de Pablo por sus iglesias (Rom 1:9; 1 Thess 1:3; 2:13) y el mandato de ''orar sin cesar'' (1 Thess 5:17) no exigen actividad literal ininterrumpida, sino un ritmo de vida marcado por la devoción regular e inquebrantable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61312, 'spa', 'Dañar o perjudicar físicamente, a menudo en contextos apocalípticos de aflicción', 'Dañar o perjudicar físicamente, a menudo en contextos apocalípticos de aflicción o destrucción. Apocalipsis emplea este sentido repetidamente: las langostas-escorpiones dañan a quienes no tienen el sello de Dios (Ap 9:4), y los dos testigos tienen poder para destruir a quienes intenten dañarlos (Ap 11:5). El español ''dañar'' hace explícita la dimensión física.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61313, 'spa', 'Hacer mal o actuar injustamente, enfatizando la transgresión moral o legal más q', 'Hacer mal o actuar injustamente, enfatizando la transgresión moral o legal más que el daño físico. Aparece 14 veces en contextos de agravio interpersonal y judicial: el dueño de la viña insiste ''no te hago injusticia'' (Mt 20:13), y Moisés confronta a un hebreo que maltrataba a otro (Hch 7:26-27). El español ''agraviar'' y el francés ''faire tort'' captan esta dimensión jurídica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61322, 'spa', 'Ser agraviado o sufrir injusticia', 'Ser agraviado o sufrir injusticia: la experiencia pasiva de ser víctima del agravio de otro. Pablo aconseja a los corintios ''¿por qué no sufrís más bien el agravio?'' (1 Cor 6:7), y Esteban ve al hebreo ''siendo maltratado'' en Egipto (Hch 7:24). La construcción pasiva destaca el punto de vista del que sufre, no del que comete la injusticia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61336, 'spa', 'Delito o fechoría', 'Designa actos concretos de injusticia o criminalidad. En Hechos aparece en contextos jurídicos: cargos que merecerían atención judicial frente a disputas religiosas fuera de la jurisdicción romana. La desestimación de Galión gira sobre esta distinción: si fuera una verdadera «fechoría», él atendería el caso. En Apocalipsis, el término acumula los actos perversos específicos de Babilonia en una totalidad que clama juicio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61337, 'spa', 'Maldad moral entendida como ausencia o violación de la justicia divina, abarcand', 'Maldad moral entendida como ausencia o violación de la justicia divina, abarcando tanto la condición interior como su expresión exterior. Pablo la usa como categoría abarcadora de la rebelión humana bajo la ira divina (Rom 1:18; 2:8; 9:14), mientras Lucas la despliega con aguda ironía en las parábolas: el mayordomo injusto (Lc 16:8), las riquezas injustas (Lc 16:9), el juez injusto (Lc 18:6). Juan la contrapone a su antónimo: ''toda injusticia es pecado'' (1 Jn 5:17), y Dios es fiel para ''limpiarnos de toda maldad'' (1 Jn 1:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61342, 'spa', 'Injusto, carente de justicia, moralmente incorrecto — la negacion de δίκαιος', 'Injusto, carente de justicia, moralmente incorrecto — la negacion de δίκαιος. Se aplica a personas que actuan injustamente (el juez injusto, Lc 18:6; el fariseo que se contrasta con los pecadores, Lc 18:11), a quienes son excluidos del reino de Dios (1 Co 6:1, 9) y a tratos o riquezas injustas (Lc 16:10-11). Jesus senala la provision imparcial de Dios para justos e injustos (Mt 5:45). Pedro habla de reservar a los injustos para el juicio (2 P 2:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61349, 'spa', 'Reprobado, descalificado', 'Que no pasa la prueba, descalificado, rechazado tras el examen — originalmente un término metalúrgico y monetario para monedas que no superan la verificación, aplicado en el NT a personas o mentes que resultan ser espiritualmente o moralmente falsas. En Ro 1:28 Pablo despliega una paronomasia devastadora: dado que no ''aprobaron'' (ἐδοκίμασαν) a Dios, Dios los entregó a una mente ''reprobada'' (ἀδόκιμον). En 1 Co 9:27 teme quedar ''descalificado'' tras predicar a otros.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61358, 'spa', 'Imposibilidad futura', 'Las traducciones multilinges lo expresan consistentemente como imposibilidad futura: español ‘será imposible’, francés ‘être impossible’. Mateo 17:20 presenta la fe como clave para revertir la imposibilidad; Lucas 1:37 presenta el poder de Dios como garantía. Ambos contextos usan el lenguaje de imposibilidad para establecer la posibilidad divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61359, 'spa', 'Imposible (referido a cosas) — Lo imposible, predicado de cosas, situaciones o p', 'Imposible (referido a cosas) — Lo imposible, predicado de cosas, situaciones o proposiciones y no de personas. Es el sentido dominante, que aparece ocho veces en los Evangelios, Pablo y Hebreos. La declaración central es la enseñanza de Jesús de que ''para los hombres esto es imposible, mas para Dios todo es posible'' (Mt 19:26; Mc 10:27; Lc 18:27). Pablo lo emplea para referirse a la impotencia de la ley para justificar: ''lo que era imposible para la ley'' (Ro 8:3; Heb 6:4, 18; 10:4; 11:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61360, 'spa', 'Impotente, débil (referido a personas) — Sin fuerza, carente de poder, predicado', 'Impotente, débil (referido a personas) — Sin fuerza, carente de poder, predicado de personas y no de cosas. En Hch 14:8, el hombre de Listra es ἀδύνατος τοῖς ποσίν, ''impotente de los pies'', describiendo una discapacidad física. En Ro 15:1, Pablo exhorta a los fuertes a sobrellevar las debilidades de τῶν ἀδυνάτων, ''los impotentes'' o ''los débiles'', aquellos que carecen de la fortaleza espiritual para discernir en asuntos discutibles.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61364, 'spa', 'Cantar en adoración', 'Cantar, particularmente en el contexto de adoración y alabanza espiritual. Cada ocurrencia neotestamentaria involucra el canto dirigido a Dios o al Cordero. Pablo lo asocia con salmodiar y hacer melodía (Ef 5:19; Col 3:16), mientras que en Apocalipsis las huestes celestiales entonan el «cántico nuevo» y el «cántico de Moisés y del Cordero» (Ap 5:9; 15:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61365, 'spa', 'Siempre', 'Denota accion perpetua, continua o habitual: ''siempre, en todo momento''. La evidencia multilingue muestra convergencia perfecta: ingles ''always'', espanol ''siempre'', frances ''toujours'', aleman ''immer''. En Hch 7:51 Esteban acusa a Israel de resistir perpetuamente al Espiritu Santo; en 2 Co 4:11 Pablo describe ser ''entregado siempre a muerte''; en Tit 1:12 capta el caracter habitual del proverbio cretense.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61366, 'spa', 'Águila o buitre', 'Ave rapaz grande, el águila (o buitre leonado en ciertos contextos), empleada tanto literal como simbólicamente. El dicho proverbial de Mt 24:28 y Lc 17:37 probablemente evoca buitres reunidos sobre un cadáver, figura de la inevitabilidad del juicio divino. Apocalipsis despliega al águila como símbolo de poder y rapidez: uno de los cuatro seres vivientes porta su semejanza (Ap 4:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61367, 'spa', 'Pan sin levadura', 'Uso sustantivado para referirse al pan sin levadura o a la Fiesta de los Panes sin Levadura (ἡ ἑορτὴ τῶν Ἀζύμων). Las ocho apariciones sinópticas designan el periodo festivo o el pan en sí: Mt 26:17, Mr 14:1, 12, Lc 22:1, 7, y Hch 12:3; 20:6. En español, ''panes sin levadura'' y ''ázimos'' nombran directamente este pan ritual concreto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61370, 'spa', 'Sin levadura (figurado)', 'Adjetivo usado predicativa o metafóricamente para describir un estado de pureza, libre de corrupción. En 1 Corintios 5:7 Pablo declara ''sois sin levadura'' (ἄζυμοί ἐστε), reinterpretando la purga pascual de la levadura como un imperativo moral de limpiar la malicia y la perversidad. Se trata de una extensión figurada del sentido literal hacia la pureza espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61373, 'spa', 'Nombre propio genealógico', 'Los cuatro idiomas transliteran el nombre de forma uniforme: Azor, Azṓr (con variaciones de acento). La doble mención en Mateo 1:13-14 establece su posición en la genealogía. Aunque históricamente oscuro, Azor representa la fiel preservación del linaje davídico durante el difícil período post-exílico, un eslabón anónimo más en la cadena mesiánica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61375, 'spa', 'Aire, atmósfera', 'El aire o atmósfera como medio físico que rodea la vida terrenal. Sin embargo, el NT inviste esta palabra cotidiana de un alcance notable: en Ef 2:2 se convierte en el ámbito de la autoridad demoníaca (''el príncipe de la potestad del aire''); en 1 Ts 4:17 es el lugar de encuentro del arrebatamiento escatológico; en 1 Co 9:26 ''golpear el aire'' y en 14:9 ''hablar al aire'' expresan acciones vanas o infructuosas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61377, 'spa', 'Inmortalidad escatológica', 'Denota exención de la muerte como naturaleza intrínseca de Dios y esperanza futura de los creyentes. En 1 Corintios el uso es climático: el cuerpo perecedero debe «revestirse» de imperecedero, lo mortal «vestirse» de inmortalidad, una imagen de vestidura para la transformación escatológica. Solo Dios «tiene» actualmente inmortalidad (1 Ti 6:16), mientras la creación la aguarda.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61378, 'spa', 'Contrario a la ley', 'Las traducciones multilinges enfatizan consistentemente la ilicitud: español ‘ilícito/ilícitas’, francés ‘illégitime’. Hechos 10:28 lo aplica a la ley judía sobre el contacto con gentiles; 1 Pedro 4:3 a las prácticas idolátricas paganas. Ambos contextos involucran límites religioso-morales. La evidencia respalda el sentido de lo contrario a la ley, especialmente la ley religiosa y moral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61380, 'spa', 'Sin ley o inicuo', 'Las traducciones multilingües enfatizan la anarquía—español ''inicuos'' (impíos/sin ley), francés preservando la forma genitiva griega, alemán ''gesetzlos'' (sin ley). Ambos pasajes de 2 Pedro lo usan para describir a los impíos: las acciones sin ley de los sodomitas (2:7) y el error de personas sin ley que podrían desviar a los creyentes (3:17). La evidencia multilingüe apoya esto como anarquía fundamental, una vida vivida sin consideración por las normas divinas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61381, 'spa', 'Rechazar o repudiar a una persona, mensaje o autoridad divina, tratándolos como ', 'Rechazar o repudiar a una persona, mensaje o autoridad divina, tratándolos como indignos de aceptación. Este es el uso predominante en el Nuevo Testamento: Herodes se niega a invalidar su juramento (Marcos 6:26), los fariseos rechazan el propósito de Dios (Lucas 7:30), y en la solemne cadena de rechazo de Lucas 10:16, desestimar a los discípulos equivale a desestimar a Cristo. El español emplea consistentemente ''rechazar'' para este sentido personal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61383, 'spa', 'Dejar sin efecto, anular o invalidar algo dotado de autoridad —una ley, pacto o ', 'Dejar sin efecto, anular o invalidar algo dotado de autoridad —una ley, pacto o propósito divino— dejándolo sin vigor. Pablo emplea este sentido al declarar ''no desecho la gracia de Dios'' (Gálatas 2:21), al razonar que nadie anula un pacto humano una vez ratificado (Gálatas 3:15), y al citar a Isaías sobre desechar la sabiduría de los sabios (1 Corintios 1:19). El español distingue claramente este sentido con ''anular'' y ''desechar''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61392, 'spa', 'Anulación o abolición', 'Las traducciones multilingües enfatizan la anulación y el dejar a un lado—español ''anulación'', francés ''rejet'' (rechazo/desecho), alemán ''Verwerfung'' (rechazo/anulación). Hebreos 7:18 lo usa para la abolición del mandamiento anterior; 9:26 para la remoción del pecado. Ambos contextos involucran la eliminación de lo que estaba anteriormente establecido—estructuras del antiguo pacto o el dominio del pecado. La evidencia multilingüe apoya esto como abolición definitiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61393, 'spa', 'Atenas', 'Atenas: la ciudad principal del Ática en Grecia, famosa como centro de filosofía, retórica y religión. Pablo la visitó durante su segundo viaje misionero y pronunció allí su célebre discurso en el Areópago (Acts 17:22-31). Lucas destaca la idolatría generalizada de la ciudad (Acts 17:16) y su curiosidad intelectual (Acts 17:21). Las cuatro referencias neotestamentarias se concentran en esta única visita, con 1 Thess 3:1 como referencia retrospectiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61394, 'spa', 'Ciudadanos de Atenas', 'Las traducciones multilingües muestran ligera variación—español distingue ''Atenienses'' en mayúscula de ''atenienses'' en minúscula, francés ''Athénien'', alemán preservando la forma plural griega. Ambos pasajes de Hechos 17 identifican la audiencia de Pablo por su ciudad: los atenienses buscadores de novedad (17:21) y el concilio que Pablo dirige (17:22). La evidencia multilingüe apoya esto como un identificador étnico-geográfico directo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61395, 'spa', 'Competir atléticamente', 'Las traducciones multilingües enfatizan consistentemente el competir—español ''compite/compitiere'' (compite), francés preservando formas griegas con diferentes modos (subjuntivo e indicativo), alemán ''kaempfen'' (luchar/competir). El uso doble en 2 Timoteo 2:5 establece la metáfora atlética: competir según las reglas es esencial para recibir la corona. La evidencia multilingüe apoya esto como esfuerzo atlético disciplinado según normas establecidas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61398, 'spa', 'Inocente o sin culpa', 'Las traducciones multilingües enfatizan uniformemente la inocencia—español ''Inocente/inocente'', francés ''innocent'', alemán preservando formas griegas con variaciones de caso. Ambos pasajes de Mateo 27 involucran declaraciones de la inocencia de Jesús: la confesión culpable de Judas (27:4) y la afirmación interesada de Pilato (27:24). La evidencia multilingüe apoya esto como sin culpa, libre de merecer castigo. La ironía es marcada: todos reconocen Su inocencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61400, 'spa', 'Playa, orilla', 'Franja arenosa o pedregosa de la costa a la orilla del agua, que sirve como lugar para desembarcar botes, reunirse o pescar. Las seis ocurrencias neotestamentarias designan el mismo rasgo físico. En los Evangelios es el escenario de la enseñanza parabólica de Jesús desde una barca (Mt 13:2) y de la aparición post-resurrección (Jn 21:4). En Hechos es tanto lugar de oración comunitaria (21:5) como destino de un desesperado intento de varar la nave (27:39-40).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61403, 'spa', 'Egipcio (gentilicio)', 'Perteneciente a Egipto o que designa a una persona egipcia. Usado como adjetivo (la sabiduría egipcia, Hch 7:22) y como sustantivo (un hombre egipcio, Hch 7:24, 28). El discurso de Esteban concentra cuatro de las cinco ocurrencias neotestamentarias, presentando a Egipto como escenario de la opresión de Israel y fuente de saber mundano. La quinta mención recuerda la destrucción de los egipcios en el Mar Rojo (Heb 11:29).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61404, 'spa', 'El nombre geográfico propio de la antigua tierra del Nilo, usado en el NT princi', 'El nombre geográfico propio de la antigua tierra del Nilo, usado en el NT principalmente en tres contextos: la huida y el regreso de la Sagrada Familia (Mt 2:13-15, 19), el recuento de Esteban sobre la estancia de Israel y el Éxodo (Hch 7:9-40), y la apelación de Hebreos al Éxodo como paradigma de fe (Heb 3:16; 8:9; 11:26-27). Apocalipsis lo despliega simbólicamente: la gran ciudad es ''llamada espiritualmente Egipto'' (Ap 11:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61409, 'spa', 'Eterno, perpetuo', 'Los equivalentes interlingüísticos enfatizan uniformemente lo eterno—español ''eterna/eternas,'' francés ''éternel/éternelles,'' alemán ''ewig/ewigen.'' Romanos 1:20 lo aplica al poder de Dios; Judas 6 a las cadenas que atan a los ángeles caídos. Ambos contextos involucran realidades últimas más allá de la limitación temporal. La evidencia multilingüe apoya esto como sempiterno, eterno en el sentido más pleno—sin principio ni fin, trascendiendo completamente el tiempo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61411, 'spa', 'Etíope', 'Los equivalentes interlingüísticos muestran ligera variación—español ''Etíope'' y ''de los Etíopes,'' francés ''Éthiopien,'' alemán preservando formas griegas. Ambas apariciones en Hechos 8:27 identifican a este oficial de la corte por su origen étnico-geográfico. La evidencia multilingüe apoya esto como una designación directa: una persona de Etiopía/Cus, la región al sur de Egipto. Lucas enfatiza este origen para destacar el alcance universal del evangelio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61412, 'spa', 'sangre', 'El fluido vital del cuerpo humano o animal, que se extiende a los dominios teológicamente ricos de la expiación sacrificial, la ratificación del pacto, la culpa por homicidio y la naturaleza humana mortal. La «sangre de Cristo» — derramada por el nuevo pacto (Mt 26:28), que asegura la redención eterna (He 9:12) — constituye el centro teológico. «Carne y sangre» denota la fragilidad humana (Mt 16:17; Gá 1:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61419, 'spa', 'Eneas', 'Los equivalentes interlingüísticos preservan el nombre griego con ligeras variaciones de caso—vocativo Αἰνέα (trato directo en 9:33) y acusativo Αἰνέαν (objeto en 9:34), reflejado en español ''Ainéas/Ainéan'' y otros idiomas. Ambas apariciones se enfocan en la sanidad dramática: el mandato de Pedro (9:33) y el contexto de fondo (9:34). La uniformidad multilingüe refleja su identidad como un individuo conocido cuya sanidad tuvo impacto regional significativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61421, 'spa', 'Alabar a Dios', 'Alabar a Dios — expresar de forma vocal, gozosa y agradecida la adoración dirigida a Dios por sus obras poderosas. Las huestes angélicas alaban a Dios en la natividad (Lc 2:13); los pastores regresan alabando a Dios (Lc 2:20); la multitud de discípulos alaba a Dios en la entrada triunfal de Jesús (Lc 19:37); el hombre sanado alaba a Dios en el templo (Hch 3:8-9); y la iglesia primitiva alaba a Dios diariamente (Hch 2:47).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61425, 'spa', 'Alabanza', 'Los equivalentes interlingüísticos se traducen uniformemente como alabanza—español ''alabanza,'' francés ''louange,'' alemán preservando la forma acusativa griega ''αἶνον.'' Mateo 21:16 cita el uso de este término en la Septuaginta para la alabanza que ofrecen los niños; Lucas 18:43 describe la respuesta de la multitud a la sanidad. Ambos contextos involucran alabanza vocal dirigida a Dios. La evidencia multilingüe apoya esto como elogio expresado, reconocimiento hablado de gloria divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61427, 'spa', 'Elección deliberada', 'Denota selección intencional tras consideración. El dilema de Pablo en Filipenses muestra la fuerza deliberativa del verbo: qué escoger, si el trabajo fructífero o estar con Cristo, implica sopesar valores. La elección divina de los creyentes (2 Ts 2:13) establece la elección como decisión divina deliberada. La elección de Moisés la historiza para los héroes de la fe: preferir conscientemente la aflicción junto al pueblo de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61428, 'spa', 'Secta o partido religioso', 'Secta o partido religioso — facción reconocida dentro de una comunidad religiosa mayor, sin connotación inherentemente peyorativa. Lucas la emplea en Hechos para el partido de los saduceos (5:17), la secta de los fariseos (15:5; 26:5) y el Camino según lo percibían los de fuera (24:5, 14; 28:22). En español, ''secta'' capta esta designación sociológica neutral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61429, 'spa', 'Herejía o facción divisiva', 'Herejía o facción divisiva que fractura la unidad comunitaria, con fuerte carga peyorativa. Pedro advierte sobre ''herejías destructoras'' introducidas por falsos maestros (2 P 2:1), Pablo enumera las ''facciones'' entre las obras de la carne (Gá 5:20) y reconoce que tales divisiones sirven para revelar a los aprobados (1 Co 11:19). Representa el giro del término desde lo neutro hacia la condena doctrinal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61435, 'spa', 'quitar, remover', 'El sentido más frecuente: remoción activa o privación. Cubre la poda de ramas (Jn 15:2), la eliminación de privilegios (Mt 21:43) y el diluvio que «arrastró» a la gente (Mt 24:39). El enfoque direccional es de alejamiento más que de ascenso. El español «quitar» captura directamente esta fuerza semántica de separación y despojo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61436, 'spa', 'tomar, recoger', 'Adquisición física: recoger un objeto del lugar donde reposa. Prominente en los milagros de alimentación donde los discípulos «recogieron» los fragmentos sobrantes (Mt 14:20; 15:37), y en el mandato de Jesús de tomar la camilla (Mt 9:6). El foco está en la obtención del objeto, no en la dirección del movimiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61439, 'spa', 'alzar, elevar', 'Elevación dirigida hacia arriba: alzar los ojos (Jn 11:41), levantar la voz (Lc 17:13) o arrojar piedras hacia lo alto (Jn 8:59). Se distingue del sentido 2 por el énfasis en la dirección vertical del movimiento más que en la toma de posesión. El español «alzar» y «levantar» captan este componente ascendente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61441, 'spa', '¡fuera con él! (clamor)', 'Modismo de clamor multitudinario que exige la ejecución o expulsión de alguien: «¡Fuera con él!» (Lc 23:18; Hch 21:36; 22:22). El español «¡Quítalo!» captura la urgencia imperativa. Funcionalmente es una demanda hostil de eliminación de una persona, distinta de la remoción física tranquila.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61443, 'spa', 'cargar, llevar', 'Porte sostenido de una carga. Es central en la llamada al discipulado: «tome su cruz» (Mt 16:24; Mc 8:34). También describe a Simón de Cirene cargando la cruz de Cristo (Mt 27:32). El énfasis recae en el transporte continuo, no en la mera acción de recoger. El español «cargar» y «llevar» reflejan esta idea de peso sostenido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61456, 'spa', 'levar anclas (náutico)', 'Uso técnico náutico: levar anclas o izar velas. Las dos ocurrencias aparecen en Hechos 27 durante el viaje de la tormenta. El español «habiendo levado anclas» confirma el sentido marítimo especializado de levantar el ancla del fondo marino para zarpar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61462, 'spa', 'ser quitado (pasivo)', 'Remoción pasiva o ser despojado. Cubre la piedra quitada del sepulcro (Jn 20:1), la exhortación de Pablo a desechar toda amargura (Ef 4:31) y la críptica cita de Isaías en Hechos 8:33. El español «fue quitado» y las formas pasivas reflejan claramente la privación sufrida por el sujeto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61491, 'spa', 'tener en suspenso', 'Modismo psicológico: «tener el alma en suspenso», es decir, mantener a alguien en ansiosa incertidumbre. Ocurre únicamente en Juan 10:24, donde la multitud presiona a Jesús para que haga una declaración mesiánica directa. El español «nos tienes en suspenso» captura la elevación figurada e inquietante del ánimo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61498, 'spa', 'Codicioso de ganancia deshonesta', 'Los equivalentes interlingüísticos enfatizan la búsqueda vergonzosa de ganancia—español ''codicioso de ganancia deshonesta'' y ''de ganancias deshonestas,'' francés preservando formas griegas, alemán ''gewinnsuechtig'' (adicto a las ganancias). Ambas epístolas pastorales usan esto en las calificaciones de liderazgo, descalificando a aquellos marcados por codicia sórdida. La evidencia multilingüe apoya esto como búsqueda de ganancia por medios vergonzosos, disposición a comprometer la integridad por dinero.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61501, 'spa', 'Vergonzoso, deshonroso', 'Vergonzoso, indigno, deshonroso: describe conductas, palabras o motivos que violan la decencia y acarrean deshonra. En 1 Cor 11:6 Pablo lo usa respecto al oprobio social de la cabeza rapada de una mujer; en 1 Cor 14:35 respecto a hablar en la asamblea; en Eph 5:12 sobre vicios paganos demasiado vergonzosos para nombrar. Titus 1:11 lo aplica a las ''ganancias deshonestas'' que motivan a los falsos maestros.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61503, 'spa', 'Vergüenza, deshonra', 'Vergüenza, deshonra o ignominia, que abarca tanto el sentimiento subjetivo de humillación como el estado objetivo de ser deshonrado. En Lc 14:9 describe el bochorno de ser relegado públicamente en un banquete. Pablo la usa para las prácticas vergonzosas ocultas que ha renunciado (2 Co 4:2) y para quienes con su conducta atraen deshonra (Fil 3:19). Hebreos 12:2 habla de la vergüenza de la crucifixión que Jesús despreció por el gozo puesto delante de él.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61507, 'spa', 'Avergonzarse, ser deshonrado', 'Sentir vergüenza o ser puesto en deshonra, abarcando la emoción interior y la humillación pública. En sus formas medias y pasivas (αἰσχύνομαι), señala la relación del creyente con el honor ante Dios. Lucas 16:3 lo emplea para vergüenza social; las epístolas se centran en la confianza escatológica: no ser avergonzados en la venida de Cristo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61508, 'spa', 'pedir, solicitar', 'Pedir, solicitar o rogar — el sentido estándar de hacer una petición ya sea a Dios en oración o a otra persona, con un tono de necesidad genuina, esperanza o súplica humilde. Este sentido central (61 ocurrencias) aparece en la gran invitación de Jesús «pedid, y se os dará» (Mt 7:7-8), la seguridad de que «vuestro Padre sabe lo que necesitáis antes de que se lo pidáis» (Mt 6:8) y el mandato de dar a quien pida (Mt 5:42).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61510, 'spa', 'exigir, demandar', 'Exigir, demandar o reclamar con urgencia, autoridad o insistencia — un registro más fuerte del pedir donde el solicitante actúa desde una posición de presión o derecho, no de sumisión humilde. Con 9 ocurrencias, este sentido aflora cuando los principales sacerdotes persuaden a la multitud para «exigir» a Barrabás (Mt 27:20) y cuando las voces de la multitud «demandando» la crucifixión de Jesús prevalecen (Lc 23:23).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61544, 'spa', 'Petición concreta', 'Se refiere a peticiones o demandas específicas, cosas pedidas de forma concreta más que el acto abstracto de pedir. El uso lucano muestra su sentido jurídico: Pilato accediendo a una demanda específica de la multitud. La instrucción paulina sobre la oración lo convierte en término técnico para aquello que se presenta a Dios en súplica. La declaración de confianza de Juan asegura la posesión de lo mismo que se pidió.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61545, 'spa', 'La causa, razón o fundamento de algo, empleado en contextos neutros o explicativ', 'La causa, razón o fundamento de algo, empleado en contextos neutros o explicativos sin implicar culpa legal. Jesús pregunta por qué αἰτία un hombre puede divorciarse de su esposa (Mateo 19:3); la mujer declara ante todos la αἰτία por la cual tocó a Jesús (Lucas 8:47). Los acusadores de Pablo en Hechos no hallan ninguna αἰτία de muerte en él (Hechos 13:28). El español emplea ''razón'' y ''causa'' para este sentido neutro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61546, 'spa', 'Un cargo formal, acusación o culpa criminal en procedimientos legales', 'Un cargo formal, acusación o culpa criminal en procedimientos legales. Se concentra en los relatos de la Pasión, donde Pilato no encuentra ninguna αἰτία en Jesús (Juan 18:38; 19:4, 6) y el título sobre la cruz establece su αἰτία (Mateo 27:37; Marcos 15:26). El español cambia a ''acusación'' y ''cargos'', revelando el registro claramente judicial. Aquí la palabra funciona como un término técnico legal para los fundamentos sobre los cuales se condena a alguien.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61551, 'spa', 'Causa o agente responsable', 'La causa, razón o agente responsable, funcionando en contextos legales y teológicos. En las declaraciones de inocencia de Jesús por Pilato (Lc 23:4, 14, 22), el neutro αἴτιον significa «motivo de acusación». En Hechos 19:40 denota justificación legítima. Hebreos 5:9 emplea el masculino αἴτιος en su sentido más elevado: Cristo como autor de la salvación eterna.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61552, 'spa', 'Repentino e inesperado', 'Las glosas multilingües enfatizan consistentemente la dimensión temporal: lo repentino y la falta de aviso. El español ''de repente'' y ''repentina'', el francés ''soudain'' y el alemán ''plötzlich'' convergen en este significado central. Ambas apariciones en el NT se encuentran en advertencias escatológicas sobre el día del Señor, donde lo inesperado sirve como motivación para la vigilancia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61553, 'spa', 'Cautividad o cautivos', 'Designa el estado o la realidad colectiva de ser llevado prisionero. En Efesios, Cristo triunfa sobre potencias hostiles capturando la cautividad misma, posiblemente liberando a los cautivos. En Apocalipsis, la doble mención establece una ley del talión: los captores se convierten en cautivos. El consenso multilingüe confirma el sentido de prisión y sujeción forzada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61555, 'spa', 'Llevar cautivo', 'Cautivar, llevar al cautiverio: apresar a alguien como prisionero, ya sea en guerra literal o en una lucha figurada por el control. Lucas 21:24 lo aplica a la deportación militar de Jerusalén. Romanos 7:23 describe el pecado como fuerza que hace prisionero. Segunda de Corintios 10:5 invierte la imagen: los creyentes llevan cautivo todo pensamiento a la obediencia de Cristo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61557, 'spa', 'eternidad (plural doxológico)', 'Uso plural doxológico: αἰῶνες en fórmulas litúrgicas e hímnicas que expresan eternidad ilimitada y acumulada — «por los siglos de los siglos» (εἰς τοὺς αἰῶνας τῶν αἰώνων). Es el sentido más frecuente con 61 ocurrencias, dominante en las bendiciones epistolares (Gá 1:5; Fil 4:20; 1 Ti 1:17) y las escenas de adoración celestial de Apocalipsis (Ap 1:6; 4:9-10; 5:13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61558, 'spa', 'eternidad (singular)', 'Perpetuidad singular: αἰών en la fórmula εἰς τὸν αἰῶνα («para siempre»), que expresa duración sin fin sin la intensificación del plural acumulado. Presente 32 veces, es la forma usada en los pronunciamientos de Jesús sobre estados permanentes — «nunca más comerás fruto» (Mt 21:19), «jamás tendrá perdón» (Mc 3:29), «no morirá jamás» (Jn 11:26).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61559, 'spa', 'siglo, era, época', 'Una era, época u orden temporal delimitado — 32 ocurrencias donde αἰών denota una dispensación temporal y no la eternidad. Las parábolas de Jesús distinguen «este siglo» del «siglo venidero» (Mt 12:32; Mc 10:30; Lc 18:30), y los discípulos preguntan por «el fin del siglo» (Mt 24:3; 28:20). El español «siglo» y «era» seleccionan vocabulario temporalmente acotado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61567, 'spa', 'eternidad pasada', 'Eternidad pretemporal: αἰών mirando hacia atrás, «desde la antigüedad», «desde siempre» o «antes de los siglos». Solo una ocurrencia clara (Hch 15:18, «conocido desde la eternidad»), pero el concepto resuena en construcciones con ἀπ'' αἰῶνος en otros lugares. El árabe distingue al-azal (eternidad pasada) de al-abad (eternidad futura), revelando una distinción que el griego colapsa en un solo vocablo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61569, 'spa', 'mundo (ámbito material)', 'El mundo material como entidad espacio-temporal, donde αἰών se aproxima a κόσμος. Sentido raro pero genuino, visible en 2 Timoteo 4:10, donde Demas abandona a Pablo «por amor a este αἰών presente» — no una época abstracta, sino el sistema mundano tangible y atractivo con sus placeres y seguridades.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61573, 'spa', 'eterno, perpetuo', 'Eterno o perpetuo, que describe lo perteneciente a una duración sin fin o al siglo venidero. Abarca 70 de 71 ocurrencias en todo el espectro teológico: la vida eterna (Mt 19:16, 29; Jn 3:16), el fuego y castigo eternos (Mt 18:8; 25:41, 46), la gloria eterna (2 Ti 2:10) y el Dios eterno (Ro 16:26).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61577, 'spa', 'para siempre', 'Sentido adverbial o intensificado que significa «para siempre, a perpetuidad», atestiguado únicamente en Filemón 1:15, donde Pablo sugiere que Onésimo fue separado «por un tiempo para que lo recibieras para siempre» (αἰώνιον). El paso del adjetivo al cuasi-adverbio se refleja en «eternamente», apartándose de la traducción adjetival estándar y sugiriendo una sutil extensión pragmática.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61578, 'spa', 'Impureza, inmundicia — Impureza o inmundicia moral o espiritual, suciedad o corr', 'Impureza, inmundicia — Impureza o inmundicia moral o espiritual, suciedad o corrupción, usado predominantemente para la inmoralidad sexual y la contaminación ética en las epístolas paulinas. Enumerado entre las obras de la carne junto con πορνεία y ἀσέλγεια (Gá 5:19; Ef 5:3; Col 3:5), aparece en el contexto del abandono judicial de la humanidad por parte de Dios (Ro 1:24), el contraste entre la vida anterior y presente del creyente (Ro 6:19; Ef 4:19) y la exhortación directa a la santidad (1 Ts 4:7; 2 Co 12:21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61581, 'spa', 'Ritual o moralmente inmundo, impuro, contaminado', 'Ritual o moralmente inmundo, impuro, contaminado. Predominantemente modifica a ''espíritu'' para designar seres demoníacos en los Sinópticos y Hechos (Mr 1:23-27; 5:2; Lc 4:36; Hch 5:16; 8:7), partiendo del marco de pureza levítico donde la LXX usa ἀκάθαρτος para el hebreo טָמֵא. También se aplica a alimentos prohibidos (Hch 10:14, 28), contaminación moral (2 Co 6:17; Ef 5:5) y las abominaciones de Apocalipsis (Ap 18:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61587, 'spa', 'Inocente y sin malicia', 'La evidencia interlingüística revela una cualidad moral-ética consistente. El español ofrece ''inocente'' e ''ingenuos'' (confiados), el francés ''inoffensif'' (inofensivo) y el alemán ''arglos'' (sin malicia). Los dos contextos del NT presentan aplicaciones contrastantes: creyentes vulnerables que necesitan protección (Romanos) versus Cristo sin pecado que no necesita purificación (Hebreos).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61588, 'spa', 'Cualquier planta espinosa o con pinchos — cardos, zarzas o arbustos espinosos — ', 'Cualquier planta espinosa o con pinchos — cardos, zarzas o arbustos espinosos — usada en la ensenanza parabolica sobre la receptividad espiritual (la semilla entre espinas, Mt 13:7, 22; Mr 4:7, 18; Lc 8:7, 14), en la sabiduria proverbial sobre reconocer el verdadero caracter (Mt 7:16; Lc 6:44), y en la corona de espinas colocada sobre Jesus por los soldados (Mt 27:29; Mr 15:17; Jn 19:2, 5). El uso en Hebreos 6:8 evoca la maldicion de Genesis 3:18.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61590, 'spa', 'Hecho de espinas', 'Todos los idiomas objetivo mantienen la especificidad botánica: español ''de espinas'', francés ''d''épines'', alemán ''Dornen''. La aplicación uniforme a la corona de espinas en ambos relatos evangélicos crea un campo semántico preciso. El adjetivo contrasta marcadamente con las coronas de oro y joyas de los reyes terrenales, destacando la humillación y el sufrimiento de la pasión de Cristo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61591, 'spa', 'Infructuoso, estéril', 'Carente de fruto o resultado productivo, ya sea en sentido botánico literal o en el uso metafórico predominante del NT que denota esterilidad espiritual o moral. La transparencia morfológica se conserva en la traducción: ''sin fruto'' en español reproduce la estructura privativa. En Mt 13:22 y Mr 4:19, los afanes del mundo ahogan la semilla y la vuelven infructuosa; en 1 Co 14:14 la mente queda sin provecho; en Ef 5:11 las obras de las tinieblas son estériles.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61595, 'spa', 'Sin cubrirse la cabeza', 'Las traducciones expresan uniformemente el estado de estar descubierto: español ''descubierta'', francés ''découvert'', alemán ''unbedeckt''. Ambos versículos ocurren dentro de un solo párrafo que aborda la misma práctica cultural. El trasfondo de la LXX y el uso clásico confirman el sentido literal de carecer de cubierta, particularmente cubierta de cabeza en contextos de adoración o decoro social.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61596, 'spa', 'Sin condena legal', 'La naturaleza forense aparece en todos los idiomas: español ''sin condena'' y ''sin juicio'', francés ''non-condamné''. Ambos contextos involucran a Pablo defendiendo sus derechos legales contra el castigo ilegal. La palabra pertenece al vocabulario técnico de la jurisprudencia romana, reflejando el uso estratégico de Pablo de su ciudadanía para protegerse y avanzar la misión del evangelio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61599, 'spa', 'Desorden e inestabilidad', 'Desorden, inestabilidad o agitación, abarcando tumulto político y disfunción comunitaria. Lucas 21:9 lo usa para perturbaciones apocalípticas. Pablo lo experimentó como tumulto en su ministerio (2 Cor 6:5) y lo temía como contienda congregacional (2 Cor 12:20). El ancla teológica es 1 Cor 14:33: Dios como antítesis de ἀκαταστασία.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61600, 'spa', 'Inestable e inquieto', 'En todos los idiomas domina el tema de inestabilidad: el español ''inestable'' y ''inquieto'', el francés preservando el término griego, el alemán ''unbeständig'' (inconstante). Los dos contextos jacobeos aplican la misma idea raíz a diferentes sujetos—el carácter de una persona y la naturaleza de un órgano—ambos enfatizando la falta de control o constancia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61602, 'spa', 'Pureza moral', 'Denota sencillez e integridad moral: estar libre de la contaminación del mal. La paradoja de Jesús empareja esta inocencia con la prudencia: pureza sin ingenuidad. En Romanos se aplica a la ignorancia deliberada del mal, pureza por no participar en él. En Filipenses se vincula con una rectitud visible: hijos de luz que resplandecen en la oscuridad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61606, 'spa', 'El acto, proceso o facultad de oír', 'El acto, proceso o facultad de oír: la capacidad de percibir y recibir sonido o palabra. Romanos 10:17 lo hace teológicamente central: la fe surge por el oír de la palabra de Cristo. La cita de Isaías por Pablo en Hechos 28:26 (''de oído oiréis y no entenderéis'') superpone la facultad con una irónica sordera espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61608, 'spa', 'Un informe, noticia, rumor o proclamación', 'Un informe, noticia, rumor o proclamación: lo que se oye, más que el acto de oír. La fama (ἀκοή) de Jesús se extiende por toda Siria (Mt 4:24); los discípulos oyen ''rumores de guerras'' (Mt 24:6; Mc 13:7). El español distingue este sentido con ''fama'' y ''noticia,'' mientras el griego subyacente depende del contexto para pasar de la facultad al contenido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61610, 'spa', 'El oído físico, el órgano corporal de la audición, que a veces funciona metoními', 'El oído físico, el órgano corporal de la audición, que a veces funciona metonímicamente como atención receptiva. En Marcos 7:35, Jesús abre los oídos (ἀκοή) de un sordo. En 2 Timoteo 4:3-4, las personas ''apartan sus oídos'' de la verdad, buscando maestros que les halaguen. El uso en plural marca este sentido concreto y anatómico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61618, 'spa', 'seguir, acompañar', 'Seguimiento físico o acompañamiento — moverse detrás o al lado de alguien, caminando tras esa persona en un viaje o entre una multitud. Es el sentido espacial básico del cual crece el significado metafórico. Destaca en escenas de multitudes: Mt 4:25 («le siguieron grandes multitudes desde Galilea»), Mt 8:1 y Mt 8:10 («ni aun en Israel he hallado tanta fe»).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61621, 'spa', 'seguir como discípulo', 'Seguir como discipulado — adherirse a un maestro como discípulo comprometido, expresando lealtad, obediencia y disposición a compartir su modo de vida. El imperativo «Sígueme» (ἀκολούθει μοι) se convierte en la llamada característica de Jesús al discipulado. Mt 9:9 (la vocación de Mateo), Mt 16:24 («Si alguno quiere venir en pos de mí, niéguese a sí mismo, tome su cruz y sígame») y Jn 21:19 son pasajes fundamentales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61649, 'spa', 'oír, percibir sonido', 'Percepción auditiva básica: oír un sonido, voz, palabra o mensaje con el oído físico. Con 360 ocurrencias, es el sentido abrumadoramente predominante, cubriendo desde Herodes que oye del nacimiento de Jesús (Mt 2:3), las multitudes que oyen su enseñanza (Mt 13:2), hasta los discípulos que oyen la voz de la nube en la Transfiguración (Mt 17:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61653, 'spa', 'escuchar, obedecer', 'Atender, prestar oído, obedecer — usos imperativos y exhortatorios que reclaman una audición receptiva que conduce a la acción. El ejemplo paradigmático es la fórmula sinóptica/apocalíptica ὁ ἔχων ὦτα ἀκουέτω («el que tiene oídos, oiga», Mt 11:15; 13:9; Ap 2:7), donde ἀκούω exige recepción espiritual y obediencia, no mera percepción sonora. Se encuentra 42 veces.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61674, 'spa', 'enterarse, recibir informe', 'Enterarse por oídas, recibir un informe o dato — el énfasis recae en la adquisición cognitiva más que en el acto auditivo en sí. Se encuentra 8 veces, frecuentemente en construcciones perfectas o resultativas: «le hemos oído decir» (Hch 6:14), «he oído de muchos acerca de este hombre» (Hch 9:13), «las cosas que has oído de mí» (2 Ti 2:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61679, 'spa', 'ser oído', 'Voz pasiva: ser oído, referido a un sonido, voz, oración o noticia que llega a los oídos de alguien sin la agencia activa del oyente. Diez ocurrencias, incluyendo el llanto de Raquel «oído» en Ramá (Mt 2:18), la noticia de Jesús «oída» en una casa (Mc 2:1), y el teológicamente cargado «tu oración ha sido oída» dirigido a Zacarías (Lc 1:13) y a Cornelio (Hch 10:31).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61687, 'spa', 'escuchar con atención', 'Escuchar, prestar atención deliberada y sostenida a un orador o mensaje. Se distingue del sentido 1 por la intencionalidad: en Lucas 2:46, el niño Jesús está «escuchando» a los maestros en el templo; en Lucas 10:39, María se sienta a los pies de Jesús «escuchando» su palabra; en Lucas 19:48, todo el pueblo «estaba pendiente de él escuchándolo». Solo 10 ocurrencias.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61750, 'spa', 'Falta de autocontrol', 'La dimensión moral aparece consistentemente: el español ''falta de dominio propio'' y ''desenfreno'', el francés ''intempérance'', el alemán preservando el griego. Los dos contextos revelan diferentes esferas—exceso moral general (Mateo) y autocontrol sexual (1 Corintios)—pero comparten el hilo común del apetito desenfrenado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61755, 'spa', 'Averiguar con exactitud', 'El tema de precisión atraviesa todas las traducciones: el español ''averiguó exactamente'', el francés ''examiner exactement'', el alemán preservando la raíz griega. Ambos versículos narran el mismo momento histórico desde ángulos diferentes, creando un contexto semántico ajustado. El uso clásico incluye investigación cuidadosa, comprensión perfecta y descripción precisa—todos convergiendo en la idea de exactitud meticulosa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61756, 'spa', 'Más exactamente (comparativo)', 'Adverbio en grado comparativo que significa ''más exactamente, con mayor precisión''. Sus cuatro apariciones se encuentran en Hechos: Priscila y Aquila exponen el Camino ''más exactamente'' a Apolos (18:26), los conspiradores planean solicitar a Pablo con el pretexto de examinar su caso ''con mayor precisión'' (23:15, 20), y Félix difiere su juicio al tener un conocimiento ''más exacto'' del Camino (24:22).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61757, 'spa', 'Con exactitud (positivo)', 'Adverbio en grado positivo que significa ''con exactitud, cuidadosamente, con precisión''. Se usa para la indagación secreta de Herodes sobre la estrella (Mt 2:8), la investigación minuciosa de Lucas (Lc 1:3), la enseñanza precisa de Apolos sobre las cosas de Jesús (Hch 18:25), la exhortación a caminar con diligencia (Ef 5:15) y el conocimiento certero de los tesalonicenses sobre el Día del Señor (1 Ts 5:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61761, 'spa', 'Langosta', 'Langosta: insecto saltador que forma enjambres, conocido como alimento permitido y como emblema bíblico de plaga devastadora. Mateo 3:4 y Marcos 1:6 lo mencionan como alimento de Juan el Bautista en el desierto, vinculándolo con la austeridad profética y Levítico 11:22. Apocalipsis 9:3, 7 describe langostas demoníacas que surgen del abismo, evocando Éxodo y Joel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61763, 'spa', 'Oidor u oyente', 'Oidor, oyente: quien escucha un mensaje, particularmente la palabra de Dios o la ley. En Romanos 2:13, Pablo establece: ''no los oidores de la ley son justos ante Dios, sino los hacedores''. Santiago 1:22-25 desarrolla este contraste, advirtiendo contra quien oye y olvida, elogiando al hacedor que actúa. El vocablo encierra una tensión: oír es necesario pero insuficiente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61764, 'spa', 'El estado o condición de ser incircunciso y, por metonimia colectiva, los pueblo', 'El estado o condición de ser incircunciso y, por metonimia colectiva, los pueblos incircuncisos (es decir, los gentiles). Domina la argumentación teológica paulina: en Romanos 2:25-27, ἀκροβυστία se opone directamente a περιτομή mientras Pablo desmantela la división circuncisión/incircuncisión. En Gálatas 5:6 y 6:15, ni la circuncisión ni la ἀκροβυστία cuentan para nada. El español emplea ''incircuncisión'' para este sentido abstracto y teológico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61766, 'spa', 'El prepucio físico en sí, con énfasis en la realidad concreta y corporal más que', 'El prepucio físico en sí, con énfasis en la realidad concreta y corporal más que en el estado abstracto o la categoría étnica. En Hechos 11:3, Pedro es confrontado específicamente por comer con hombres ''que tienen prepucio'' (ἀκροβυστίαν ἔχοντας), donde el enfoque recae en la marca física que distingue a los incircuncisos. El español emplea ''prepucio'' en lugar de la abstracta ''incircuncisión'' para este sentido corporal concreto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61768, 'spa', 'Piedra angular', 'Las traducciones interlingüísticas preservan la metáfora arquitectónica: el español ''piedra angular'', el francés preservando el griego, el alemán ''Eckstein'' (piedra de esquina). Ambos pasajes del NT son cristológicos, aplicando profecías veterotestamentarias de la piedra angular a Jesús. La imagen arquitectónica transmite el papel esencial y fundacional de Cristo al unir creyentes judíos y gentiles en un solo edificio espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61770, 'spa', 'Extremo, confín', 'El punto más lejano o extremidad de una extensión espacial, usado para límites cósmicos o geográficos. En Mt 24:31 y el paralelo de Mr 13:27, la frase ''desde los extremos de los cielos hasta los extremos de ellos'' describe el alcance total de la reunión divina en el éschaton. El español extremos enfatiza el límite último. La repetición en estos dichos escatológicos subraya la exhaustividad de la acción redentora de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61772, 'spa', 'Punta, extremo físico', 'La punta o extremo de un objeto físico o parte del cuerpo, a escala pequeña e íntima. En Lc 16:24, el hombre rico en el Hades suplica que Lázaro moje la punta (ἄκρον) de su dedo en agua, detalle conmovedor que enfatiza el abismo entre ambos. En Heb 11:21, Jacob adora apoyado sobre la punta de su bastón. El español punta capta con precisión este sentido concreto y táctil.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61774, 'spa', 'Aquila (nombre propio)', 'Nombre propio Aquila (en griego Ἀκύλας), que designa al fabricante de tiendas judeocristiano originario del Ponto quien, junto con su esposa Priscila, llegó a ser uno de los colaboradores más cercanos de Pablo. Las seis apariciones neotestamentarias se refieren al mismo individuo: en la narrativa de Hechos (18:2, 18, 26) y en saludos epistolares (Ro 16:3; 1 Co 16:19; 2 Ti 4:19), siempre mencionado junto a Priscila.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61778, 'spa', 'Anulación autoritativa', 'Denota la cancelación con autoridad o el acto de dejar algo sin efecto. La acusación de Jesús es severa: la tradición humana ha invalidado jurídicamente el mandamiento divino, invirtiendo la jerarquía de autoridad. El argumento de Pablo en Gálatas protege la prioridad del pacto: la ley mosaica posterior no puede anular la promesa abrahémica anterior.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61781, 'spa', 'Frasco de alabastro', 'Pequeño recipiente sin asas para perfume, típicamente tallado en piedra de alabastro, diseñado con un cuello sellado para preservar ungüentos costosos. La evidencia multilingüe lo traduce consistentemente como recipiente y no como el mineral: en español, ''frasco de alabastro''. Cada uso neotestamentario involucra la unción de Jesús con nardo o perfume de gran precio, subrayando un acto de devoción sacrificial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61782, 'spa', 'Jactancia arrogante', 'El tema de jactancia domina las traducciones: el español ''vanagloria'' y ''arrogancias'', el francés preservando el griego, el alemán ''Prahlerei'' (fanfarronería). Santiago lo aplica a la planificación comercial presuntuosa, mientras Juan lo usa más ampliamente para el orgullo mundano. Ambos contextos critican la confianza egocéntrica que excluye a Dios de la consideración.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61783, 'spa', 'Jactancioso arrogante', 'Las glosas interlingüísticas enfatizan el carácter jactancioso: español ''jactanciosos,'' francés y alemán ''Prahler'' (fanfarrones). Ambas listas de vicios paulinas ubican a los jactanciosos entre aquellos caracterizados por la auto-exaltación. La asociación clásica del término con sofistas fraudulentos y charlatanes ambulantes añade una dimensión de pretensión vacía y afirmaciones poco confiables.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61784, 'spa', 'Lamentar ruidosamente', 'Las traducciones capturan diferentes aspectos: español ''lamentando'' y ''que resuena,'' francés ''hurler'' (aullar) y ''pousser des cris,'' alemán ''lärmen'' (hacer ruido). El contexto de Marcos claramente indica lamento fúnebre, mientras que la referencia de Pablo es al ruido vacío. El trasfondo clásico en gritos de batalla y ritos báquicos muestra cómo la intensidad emocional y la vocalización fuerte unen estos significados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61786, 'spa', 'Incapacidad de hablar', 'Designa la condición de no poder hablar, ya sea por impedimento físico o por opresión espiritual. Las sanidades en Marcos vinculan la mudez con la aflicción demoniaca: el espíritu impide el habla y su expulsión la restaura. El contexto antiguo no distinguía tajantemente entre causas médicas y espirituales de la mudez.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61787, 'spa', 'Sal', 'Sal — la sustancia mineral usada literalmente para sazonar y conservar, y metafóricamente para la influencia preservadora y purificadora de los discípulos en el mundo. Jesús declara ''Vosotros sois la sal de la tierra'' (Mt 5:13) y advierte contra la sal que pierde su sabor; Marcos 9:50 la emplea como símbolo de vitalidad espiritual interior y disposición pacífica; Colosenses 4:6 la aplica al habla llena de gracia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61789, 'spa', 'Ungir con aceite', 'Aplicar aceite, ungento o perfume sobre el cuerpo de una persona frotandolo, abarcando actos de aseo personal (Mt 6:17, ungir la cabeza al ayunar), devocion y hospitalidad generosa (Lc 7:38, 46; Jn 11:2; 12:3, ungir los pies de Jesus), oracion por sanidad (Mr 6:13; Stg 5:14, ungir con aceite a los enfermos) y preparacion para la sepultura (Mr 16:1). Es el termino fisico y cotidiano para ungir, no el ceremonial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61798, 'spa', 'Un gallo, ave domestica cuyo canto antes del amanecer servia como marcador natur', 'Un gallo, ave domestica cuyo canto antes del amanecer servia como marcador natural del tiempo en el mundo antiguo. Las 12 ocurrencias en el NT se concentran en el relato de la Pasion sobre la negacion de Pedro: Jesus predice que el gallo cantara antes de la triple negacion de Pedro (Mt 26:34; Mr 14:30; Lc 22:34; Jn 13:38), y el canto real confirma la profecia (Mt 26:74-75; Mr 14:68, 72; Lc 22:60-61; Jn 18:27).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61799, 'spa', 'Habitante de Alejandría', 'La identificación étnico-geográfica aparece uniformemente: español ''alejandrino,'' francés ''Alexandrin.'' Los dos contextos presentan a los alejandrinos bajo luces diferentes—oponentes de Esteban (Hechos 6) y el maestro talentoso Apolos (Hechos 18). La prominencia de Alejandría en la vida de la diáspora judía, hogar de eruditos como Filón y los traductores de la Septuaginta, hace significativa esta designación para comprender la vida judía.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61800, 'spa', 'De Alejandría', 'Todas las traducciones preservan la designación geográfica: español ''alejandrino,'' francés ''Alexandrin.'' Ambas referencias ocurren dentro de la narrativa del viaje de Pablo a Roma, identificando barcos de grano de Alejandría. El adjetivo marca el puerto de origen de los barcos, reflejando el papel de Alejandría como la fuente mediterránea primaria de grano para Roma y un importante centro de comercio marítimo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61801, 'spa', 'Alejandro (nombre propio)', 'Nombre personal Ἀλέξανδρος (''defensor de hombres''), aplicado en el NT a varios individuos. La forma griega se conserva de manera consistente en las distintas lenguas, reflejando su condición de nombre propio establecido como préstamo léxico. Los múltiples portadores abarcan desde la narrativa de la pasión (Mr 15:21) hasta las epístolas paulinas (1 Ti 1:20; 2 Ti 4:14), pasando por Hechos (4:6; 19:33).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61803, 'spa', 'Harina de trigo', 'El término culinario se traduce consistentemente: español ''harina,'' francés ''farine,'' alemán preservando la raíz griega. Ambos relatos evangélicos presentan contextos parabólicos idénticos. La harina como medio para la obra de la levadura la hace central a la imaginería de la parábola—el poder transformador del reino obra a través del material ordinario de la vida diaria, así como la levadura obra a través de la harina para crear pan.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61804, 'spa', 'verdad, realidad', 'La cualidad de ser verdadero, real o conforme a los hechos y a la realidad divina. Abarca el habla honesta (Mc 5:33, «le dijo toda la verdad»), la fidelidad divina y la verdad del evangelio (Gá 2:5), y el sentido teológico joánico donde Jesús encarna la verdad misma (Jn 14:6). La uniformidad en las traducciones —español ''verdad'', alemán ''Wahrheit''— confirma su núcleo semántico estable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61809, 'spa', 'Hablar la verdad', 'Las traducciones multilingües enfatizan el habla veraz: español ''diciéndoos verdad'' y ''hablando verdad'', francés preservando el griego, alemán ''die Wahrheit reden'' (hablar la verdad). Gálatas destaca la potencial ofensa por decir la verdad, mientras que Efesios equilibra verdad con amor. Ambos contextos valoran la comunicación honesta como esencial para relaciones cristianas saludables.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61810, 'spa', 'Verdadero, real o genuino en el sentido primario', 'Verdadero, real o genuino en el sentido primario: aplicado a declaraciones, testimonios, enseñanzas y realidades divinas que corresponden a los hechos y no son engañosas. Se reconoce a Jesús como quien enseña ''el camino de Dios en verdad'' (Mt 22:16), Dios es declarado ''verdadero'' cuando todo hombre es mentiroso (Rom 3:4), y Jesús afirma que su testimonio es ''verdadero'' (Jn 5:31-32, 8:26).');